-- Modèles de TDR

INSERT INTO document_templates (code, type, titre, nature_marche, corps_metier_id, version, sections, meta)
SELECT 'TDR-BTP', 'TDR', 'Termes de référence — BTP / Génie civil / Bâtiment', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser le programme (usage du bâtiment, effectifs accueillis), la parcelle et l'état des études (APS/APD, sol).","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Programme fonctionnel et surfaces","Statut foncier de la parcelle et accès au site","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Construire / réhabiliter [●] m² de [type de bâtiment] conformes au programme fonctionnel, réceptionnés avant le [●].\n2. Garantir la solidité et la durabilité des ouvrages (études de sol et notes de calcul validées).\n3. Livrer un dossier des ouvrages exécutés (DOE) complet.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Construire / réhabiliter [●] m² de [type de bâtiment] conformes au programme fonctionnel, réceptionnés avant le [●].","Garantir la solidité et la durabilité des ouvrages (études de sol et notes de calcul validées).","Livrer un dossier des ouvrages exécutés (DOE) complet.","Un indicateur et une cible par objectif"],"exemple":"Construire / réhabiliter [●] m² de [type de bâtiment] conformes au programme fonctionnel, réceptionnés avant le [●].","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Consistance des travaux et spécifications techniques","obligatoire":true,"consigne":"Décrire les ouvrages, leurs caractéristiques, les quantités principales, le site et les spécifications techniques applicables.","contenu":"1. Installation de chantier, signalisation et clôture : [●]\n2. Terrassements et fondations selon l'étude géotechnique : [●]\n3. Gros œuvre (infrastructure, superstructure, maçonnerie) : [●] m²\n4. Second œuvre (étanchéité, menuiseries, revêtements, peinture) : [●]\n5. Lots techniques (électricité, plomberie, climatisation, courants faibles) : [●]\n6. Voiries et réseaux divers (VRD), aménagements extérieurs : [●]\n7. Repli de chantier et remise en état des lieux\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire les ouvrages, leurs caractéristiques, les quantités principales, le site et les spécifications techniques applicables.","points":["Installation de chantier, signalisation et clôture : [●]","Terrassements et fondations selon l'étude géotechnique : [●]","Gros œuvre (infrastructure, superstructure, maçonnerie) : [●] m²","Second œuvre (étanchéité, menuiseries, revêtements, peinture) : [●]","Lots techniques (électricité, plomberie, climatisation, courants faibles) : [●]","Voiries et réseaux divers (VRD), aménagements extérieurs : [●]","Repli de chantier et remise en état des lieux"],"exemple":"Installation de chantier, signalisation et clôture : [●]","erreurs":["Saison des pluies (juin à octobre) : adapter le planning et les protections","Qualité des granulats et du sable (salinité) en zone côtière","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Planning, jalons et documents d'exécution","obligatoire":true,"consigne":"Lister les jalons, les documents d'exécution à fournir (plans, notes de calcul, DOE) et leurs échéances.","contenu":"L1 — Plan d'installation de chantier et planning d'exécution : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Plans d'exécution et notes de calcul visés par le maître d'œuvre : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — Rapports mensuels d'avancement avec photos datées : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — Dossier des ouvrages exécutés (DOE) et plans de récolement : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Plan d'installation de chantier et planning d'exécution","Plans d'exécution et notes de calcul visés par le maître d'œuvre","Rapports mensuels d'avancement avec photos datées","Dossier des ouvrages exécutés (DOE) et plans de récolement","Lien entre livrable et paiement"],"exemple":"Plan d'installation de chantier et planning d'exécution : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- Conducteur de travaux (ingénieur ou technicien supérieur du BTP) : [●]\n- Chef de chantier : [●]\n- Responsable hygiène, sécurité et environnement (HSE) : [●]\n- Matériel de chantier minimal (bétonnière, vibreur, échafaudages, engins) : [●]\n- Références de chantiers similaires de montant comparable : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["Conducteur de travaux (ingénieur ou technicien supérieur du BTP)","Chef de chantier","Responsable hygiène, sécurité et environnement (HSE)","Matériel de chantier minimal (bétonnière, vibreur, échafaudages, engins)","Références de chantiers similaires de montant comparable","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"Conducteur de travaux (ingénieur ou technicien supérieur du BTP) : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) du site des travaux : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Période d'hivernage et jours non travaillés","Délai de préparation et d'approbation des plans"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Normes sénégalaises (ASN) ou internationales équivalentes pour les matériaux (ciment, acier, granulats) ; Règles de calcul et de construction en vigueur (béton armé, parasismique le cas échéant).","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Normes sénégalaises (ASN) ou internationales équivalentes pour les matériaux (ciment, acier, granulats)","Références usuelles (à confirmer auprès de l'autorité compétente) : Règles de calcul et de construction en vigueur (béton armé, parasismique le cas échéant)","Références usuelles (à confirmer auprès de l'autorité compétente) : Code de la construction et réglementation de l'urbanisme (permis de construire)","Saison des pluies (juin à octobre) : adapter le planning et les protections","Qualité des granulats et du sable (salinité) en zone côtière","Études de sol obligatoires avant tout dimensionnement des fondations","Contrôle des matériaux par un laboratoire agréé"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Conformité aux plans et au cahier des clauses techniques\n- Essais et épreuves réussis (béton, étanchéité, installations électriques)\n- Levée des réserves avant réception provisoire\n- DOE remis avant réception définitive\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Conformité aux plans et au cahier des clauses techniques","Essais et épreuves réussis (béton, étanchéité, installations électriques)","Levée des réserves avant réception provisoire","DOE remis avant réception définitive","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Garanties, assurances et obligations du titulaire","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"TRAVAUX","version":2,"questions":["Quelle est la nature de l'ouvrage (bâtiment administratif, école, centre de santé, logement…) et sa surface ?","Où se situe le site (commune, région) et son accès est-il dégagé ?","Les études (APS/APD, sol, plans) existent-elles ? Qui les a réalisées ?","Quel est le délai souhaité et les contraintes (hivernage, occupation des lieux) ?","Les travaux sont-ils alloties (gros œuvre / lots techniques) ?"],"references":["Normes sénégalaises (ASN) ou internationales équivalentes pour les matériaux (ciment, acier, granulats)","Règles de calcul et de construction en vigueur (béton armé, parasismique le cas échéant)","Code de la construction et réglementation de l'urbanisme (permis de construire)"],"vigilance":["Saison des pluies (juin à octobre) : adapter le planning et les protections","Qualité des granulats et du sable (salinité) en zone côtière","Études de sol obligatoires avant tout dimensionnement des fondations","Contrôle des matériaux par un laboratoire agréé"]}$j$::jsonb FROM corps_metiers cm WHERE cm.code = 'BTP'
ON CONFLICT (code) DO UPDATE SET titre = EXCLUDED.titre, nature_marche = EXCLUDED.nature_marche, corps_metier_id = EXCLUDED.corps_metier_id, version = EXCLUDED.version, sections = EXCLUDED.sections, meta = EXCLUDED.meta;

