SELECT 'TDR-ROUTES_OUVRAGES', 'TDR', 'Termes de référence — Routes, pistes rurales et ouvrages d''art', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser l'axe (début, fin, linéaire), le trafic, le niveau de service visé et l'état des études.","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Classement du réseau (routes nationales, régionales, pistes rurales)","Trafic et désenclavement attendu (populations, zones de production)","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Réhabiliter / construire [●] km de route entre [●] et [●] respectant la structure de chaussée prévue.\n2. Assurer l'écoulement des eaux (ouvrages hydrauliques) et la sécurité des usagers.\n3. Réduire le temps de parcours et le coût d'exploitation des véhicules sur l'axe.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Réhabiliter / construire [●] km de route entre [●] et [●] respectant la structure de chaussée prévue.","Assurer l'écoulement des eaux (ouvrages hydrauliques) et la sécurité des usagers.","Réduire le temps de parcours et le coût d'exploitation des véhicules sur l'axe.","Un indicateur et une cible par objectif"],"exemple":"Réhabiliter / construire [●] km de route entre [●] et [●] respectant la structure de chaussée prévue.","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Consistance des travaux et spécifications techniques","obligatoire":true,"consigne":"Décrire les ouvrages, leurs caractéristiques, les quantités principales, le site et les spécifications techniques applicables.","contenu":"1. Installation, déviations provisoires et signalisation de chantier : [●]\n2. Terrassements, purges et mise en forme de la plateforme : [●] m³\n3. Couche de fondation, couche de base (matériaux traités ou non) : [●] m³\n4. Revêtement (enduit superficiel, enrobé, béton bitumineux) : [●] m²\n5. Ouvrages hydrauliques (buses, dalots, ponts) : [●] unités\n6. Assainissement latéral, signalisation horizontale et verticale, dispositifs de sécurité\n7. Repli de chantier et remise en état des carrières et emprunts\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire les ouvrages, leurs caractéristiques, les quantités principales, le site et les spécifications techniques applicables.","points":["Installation, déviations provisoires et signalisation de chantier : [●]","Terrassements, purges et mise en forme de la plateforme : [●] m³","Couche de fondation, couche de base (matériaux traités ou non) : [●] m³","Revêtement (enduit superficiel, enrobé, béton bitumineux) : [●] m²","Ouvrages hydrauliques (buses, dalots, ponts) : [●] unités","Assainissement latéral, signalisation horizontale et verticale, dispositifs de sécurité","Repli de chantier et remise en état des carrières et emprunts"],"exemple":"Installation, déviations provisoires et signalisation de chantier : [●]","erreurs":["Sourcing des matériaux (latérite, graveleux) et distance de transport","Déplacement des réseaux concessionnaires (eau, électricité, télécoms)","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Planning, jalons et documents d'exécution","obligatoire":true,"consigne":"Lister les jalons, les documents d'exécution à fournir (plans, notes de calcul, DOE) et leurs échéances.","contenu":"L1 — Programme d'exécution, plan d'assurance qualité et planning : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Résultats des essais de laboratoire (matériaux, compactage, portance) : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — Plans de récolement et métrés contradictoires : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — Rapports mensuels d'avancement et décomptes : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Programme d'exécution, plan d'assurance qualité et planning","Résultats des essais de laboratoire (matériaux, compactage, portance)","Plans de récolement et métrés contradictoires","Rapports mensuels d'avancement et décomptes","Lien entre livrable et paiement"],"exemple":"Programme d'exécution, plan d'assurance qualité et planning : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- Ingénieur routes / conducteur de travaux routiers : [●]\n- Topographe : [●]\n- Technicien de laboratoire de chantier : [●]\n- Parc d'engins (niveleuse, compacteur, pelle, camions, centrale d'enrobage si applicable) : [●]\n- Références de chantiers routiers de linéaire et de montant comparables : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["Ingénieur routes / conducteur de travaux routiers","Topographe","Technicien de laboratoire de chantier","Parc d'engins (niveleuse, compacteur, pelle, camions, centrale d'enrobage si applicable)","Références de chantiers routiers de linéaire et de montant comparables","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"Ingénieur routes / conducteur de travaux routiers : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) du site des travaux : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Interruptions liées à l'hivernage","Délai de libération des emprises"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Guides et normes routières en vigueur au Sénégal (à confirmer auprès de l'AGEROUTE ou du ministère chargé des infrastructures) ; Réglementation sur l'ouverture de carrières et d'emprunts.","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Guides et normes routières en vigueur au Sénégal (à confirmer auprès de l'AGEROUTE ou du ministère chargé des infrastructures)","Références usuelles (à confirmer auprès de l'autorité compétente) : Réglementation sur l'ouverture de carrières et d'emprunts","Références usuelles (à confirmer auprès de l'autorité compétente) : Études d'impact environnemental et social pour les travaux concernés (DEEC)","Sourcing des matériaux (latérite, graveleux) et distance de transport","Déplacement des réseaux concessionnaires (eau, électricité, télécoms)","Indemnisation des occupations et expropriations avant démarrage","Contrôle indépendant des essais de laboratoire"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Contrôle géométrique et de portance de la plateforme et des couches\n- Essais conformes aux seuils du cahier des clauses techniques\n- Ouvrages hydrauliques fonctionnels et signalisation complète\n- Réception provisoire puis définitive après la période de garantie\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Contrôle géométrique et de portance de la plateforme et des couches","Essais conformes aux seuils du cahier des clauses techniques","Ouvrages hydrauliques fonctionnels et signalisation complète","Réception provisoire puis définitive après la période de garantie","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Garanties, assurances et obligations du titulaire","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"TRAVAUX","version":2,"questions":["Quel est l'axe concerné, son linéaire et sa classification ?","Quel type de revêtement est visé ?","Y a-t-il des ouvrages d'art ou hydrauliques à construire ?","Les études techniques et d'impact sont-elles disponibles ? Les emprises sont-elles libérées ?","Quelles carrières ou emprunts sont prévus ?"],"references":["Guides et normes routières en vigueur au Sénégal (à confirmer auprès de l'AGEROUTE ou du ministère chargé des infrastructures)","Réglementation sur l'ouverture de carrières et d'emprunts","Études d'impact environnemental et social pour les travaux concernés (DEEC)"],"vigilance":["Sourcing des matériaux (latérite, graveleux) et distance de transport","Déplacement des réseaux concessionnaires (eau, électricité, télécoms)","Indemnisation des occupations et expropriations avant démarrage","Contrôle indépendant des essais de laboratoire"]}$j$::jsonb FROM corps_metiers cm WHERE cm.code = 'ROUTES_OUVRAGES'
