SELECT 'TDR-ENERGIE', 'TDR', 'Termes de référence — Énergie et hydraulique', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser la localité ou le réseau, la puissance et la demande à satisfaire, et l'opérateur qui exploitera les ouvrages.","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Puissance et énergie à fournir, nombre d'abonnés","Opérateur exploitant (SENELEC, ASER ou autre)","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Mettre en service [●] km de réseau / [●] kW de capacité avant le [●].\n2. Raccorder [●] ménages ou équipements au réseau.\n3. Garantir la sécurité des personnes et la qualité de la fourniture.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Mettre en service [●] km de réseau / [●] kW de capacité avant le [●].","Raccorder [●] ménages ou équipements au réseau.","Garantir la sécurité des personnes et la qualité de la fourniture.","Un indicateur et une cible par objectif"],"exemple":"Mettre en service [●] km de réseau / [●] kW de capacité avant le [●].","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Consistance des travaux et spécifications techniques","obligatoire":true,"consigne":"Décrire les ouvrages, leurs caractéristiques, les quantités principales, le site et les spécifications techniques applicables.","contenu":"1. Lignes moyenne tension (MT) : [●] km\n2. Postes de transformation MT/BT : [●] unités de [●] kVA\n3. Réseau basse tension (BT) et branchements : [●] km, [●] branchements\n4. Éclairage public : [●] points lumineux\n5. Mise à la terre, protections et comptage\n6. Essais, mise en service et raccordement au réseau existant\n7. Formation des agents d'exploitation\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire les ouvrages, leurs caractéristiques, les quantités principales, le site et les spécifications techniques applicables.","points":["Lignes moyenne tension (MT) : [●] km","Postes de transformation MT/BT : [●] unités de [●] kVA","Réseau basse tension (BT) et branchements : [●] km, [●] branchements","Éclairage public : [●] points lumineux","Mise à la terre, protections et comptage","Essais, mise en service et raccordement au réseau existant","Formation des agents d'exploitation"],"exemple":"Lignes moyenne tension (MT) : [●] km","erreurs":["Consignation et sécurité électrique pendant les travaux","Approbation des matériels par l'exploitant avant commande","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Planning, jalons et documents d'exécution","obligatoire":true,"consigne":"Lister les jalons, les documents d'exécution à fournir (plans, notes de calcul, DOE) et leurs échéances.","contenu":"L1 — Études d'exécution et schémas unifilaires approuvés par l'exploitant : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Rapports d'essais et procès-verbaux de mise en service : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — Plans de récolement et carnets de maintenance : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — Dossier des ouvrages exécutés : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Études d'exécution et schémas unifilaires approuvés par l'exploitant","Rapports d'essais et procès-verbaux de mise en service","Plans de récolement et carnets de maintenance","Dossier des ouvrages exécutés","Lien entre livrable et paiement"],"exemple":"Études d'exécution et schémas unifilaires approuvés par l'exploitant : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- Ingénieur électricien : [●]\n- Chef de chantier électricité / lignes : [●]\n- Habilitations électriques du personnel : [●]\n- Matériel de levage, de tirage et d'essais : [●]\n- Références de réseaux électriques de même nature : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["Ingénieur électricien","Chef de chantier électricité / lignes","Habilitations électriques du personnel","Matériel de levage, de tirage et d'essais","Références de réseaux électriques de même nature","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"Ingénieur électricien : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) du site des travaux : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Délais de consignation et d'autorisation de l'exploitant","Livraison des matériels importés"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Normes et prescriptions techniques de l'exploitant (à confirmer auprès de SENELEC ou de l'ASER) ; Règles de la Commission de régulation du secteur de l'électricité (CRSE).","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Normes et prescriptions techniques de l'exploitant (à confirmer auprès de SENELEC ou de l'ASER)","Références usuelles (à confirmer auprès de l'autorité compétente) : Règles de la Commission de régulation du secteur de l'électricité (CRSE)","Références usuelles (à confirmer auprès de l'autorité compétente) : Normes internationales équivalentes (CEI) pour les matériels","Consignation et sécurité électrique pendant les travaux","Approbation des matériels par l'exploitant avant commande","Emprises et servitudes des lignes","Délais d'approvisionnement des transformateurs et câbles"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Essais d'isolement, de continuité et de mise à la terre conformes\n- Mise sous tension et fonctionnement nominal\n- Conformité des matériels aux fiches techniques approuvées\n- Remise du dossier des ouvrages exécutés\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Essais d'isolement, de continuité et de mise à la terre conformes","Mise sous tension et fonctionnement nominal","Conformité des matériels aux fiches techniques approuvées","Remise du dossier des ouvrages exécutés","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Garanties, assurances et obligations du titulaire","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"TRAVAUX","version":2,"questions":["Quel type d'ouvrage (ligne, poste, éclairage public, centrale) et quelle puissance ?","Où se situe le site et quel est le point de raccordement ?","Quel opérateur exploitera et réceptionnera les ouvrages ?","Quelles études existent déjà (APS, schéma, relevés) ?","Quels matériels doivent être importés ?"],"references":["Normes et prescriptions techniques de l'exploitant (à confirmer auprès de SENELEC ou de l'ASER)","Règles de la Commission de régulation du secteur de l'électricité (CRSE)","Normes internationales équivalentes (CEI) pour les matériels"],"vigilance":["Consignation et sécurité électrique pendant les travaux","Approbation des matériels par l'exploitant avant commande","Emprises et servitudes des lignes","Délais d'approvisionnement des transformateurs et câbles"]}$j$::jsonb FROM corps_metiers cm WHERE cm.code = 'ENERGIE'
ON CONFLICT (code) DO UPDATE SET titre = EXCLUDED.titre, nature_marche = EXCLUDED.nature_marche, corps_metier_id = EXCLUDED.corps_metier_id, version = EXCLUDED.version, sections = EXCLUDED.sections, meta = EXCLUDED.meta;

