SELECT 'TDR-ENERGIES_RENOUVELABLES', 'TDR', 'Termes de référence — Énergies renouvelables et électrification rurale', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser la localité, les usages (domestique, productif, santé, éducation), la demande et le modèle d'exploitation.","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Besoins énergétiques estimés et usages productifs","Modèle de gestion et de paiement du service (exploitant, tarif, maintenance)","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Installer [●] kWc de production solaire et [●] kWh de stockage pour alimenter [●] ménages / équipements.\n2. Assurer une disponibilité du service d'au moins [●] % par an.\n3. Transférer les compétences d'exploitation et de maintenance aux acteurs locaux.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Installer [●] kWc de production solaire et [●] kWh de stockage pour alimenter [●] ménages / équipements.","Assurer une disponibilité du service d'au moins [●] % par an.","Transférer les compétences d'exploitation et de maintenance aux acteurs locaux.","Un indicateur et une cible par objectif"],"exemple":"Installer [●] kWc de production solaire et [●] kWh de stockage pour alimenter [●] ménages / équipements.","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Consistance des travaux et spécifications techniques","obligatoire":true,"consigne":"Décrire les ouvrages, leurs caractéristiques, les quantités principales, le site et les spécifications techniques applicables.","contenu":"1. Centrale photovoltaïque (modules, onduleurs, structures) : [●] kWc\n2. Stockage par batteries et système de gestion : [●] kWh\n3. Mini-réseau de distribution et branchements : [●] ml\n4. Kits solaires domestiques ou équipements de pompage solaire : [●] unités\n5. Supervision et télégestion le cas échéant\n6. Essais de performance et mise en service\n7. Formation des techniciens locaux, plan de maintenance\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire les ouvrages, leurs caractéristiques, les quantités principales, le site et les spécifications techniques applicables.","points":["Centrale photovoltaïque (modules, onduleurs, structures) : [●] kWc","Stockage par batteries et système de gestion : [●] kWh","Mini-réseau de distribution et branchements : [●] ml","Kits solaires domestiques ou équipements de pompage solaire : [●] unités","Supervision et télégestion le cas échéant","Essais de performance et mise en service","Formation des techniciens locaux, plan de maintenance"],"exemple":"Centrale photovoltaïque (modules, onduleurs, structures) : [●] kWc","erreurs":["Qualité et garantie des batteries (durée de vie réelle)","Dimensionnement tenant compte de l'ensoleillement et des pertes (poussière, chaleur)","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Planning, jalons et documents d'exécution","obligatoire":true,"consigne":"Lister les jalons, les documents d'exécution à fournir (plans, notes de calcul, DOE) et leurs échéances.","contenu":"L1 — Note de dimensionnement et schémas électriques : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Fiches techniques et certificats des équipements : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — Rapport de mise en service et de performance : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — Manuel d'exploitation et plan de maintenance : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Note de dimensionnement et schémas électriques","Fiches techniques et certificats des équipements","Rapport de mise en service et de performance","Manuel d'exploitation et plan de maintenance","Lien entre livrable et paiement"],"exemple":"Note de dimensionnement et schémas électriques : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- Ingénieur en énergies renouvelables : [●]\n- Techniciens installateurs qualifiés : [●]\n- Capacité de maintenance et stock de pièces détachées : [●]\n- Références d'installations solaires comparables : [●]\n- Présence ou partenaire de maintenance au Sénégal : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["Ingénieur en énergies renouvelables","Techniciens installateurs qualifiés","Capacité de maintenance et stock de pièces détachées","Références d'installations solaires comparables","Présence ou partenaire de maintenance au Sénégal","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"Ingénieur en énergies renouvelables : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) du site des travaux : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Délais d'importation des modules et batteries","Accès aux villages isolés"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Cadre de l'électrification rurale (ASER) et règles de la CRSE (à confirmer) ; Normes internationales équivalentes (CEI) pour modules, onduleurs et batteries.","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Cadre de l'électrification rurale (ASER) et règles de la CRSE (à confirmer)","Références usuelles (à confirmer auprès de l'autorité compétente) : Normes internationales équivalentes (CEI) pour modules, onduleurs et batteries","Références usuelles (à confirmer auprès de l'autorité compétente) : Réglementation douanière et fiscale applicable aux équipements solaires","Qualité et garantie des batteries (durée de vie réelle)","Dimensionnement tenant compte de l'ensoleillement et des pertes (poussière, chaleur)","Maintenance après réception : prévoir un contrat ou un fonds dédié","Protection contre le vol et le vandalisme"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Essais de performance conformes à la puissance garantie\n- Fonctionnement des protections et de la supervision\n- Équipements conformes aux fiches techniques approuvées\n- Formation réalisée et manuels remis\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Essais de performance conformes à la puissance garantie","Fonctionnement des protections et de la supervision","Équipements conformes aux fiches techniques approuvées","Formation réalisée et manuels remis","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Garanties, assurances et obligations du titulaire","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"TRAVAUX","version":2,"questions":["Quels usages l'installation doit-elle alimenter et pour combien de bénéficiaires ?","Quelle puissance et quel stockage sont estimés ?","Qui exploitera et entretiendra les installations ?","Quelle localité et quel accès au site ?","Quelle garantie et quel service après-vente sont exigés ?"],"references":["Cadre de l'électrification rurale (ASER) et règles de la CRSE (à confirmer)","Normes internationales équivalentes (CEI) pour modules, onduleurs et batteries","Réglementation douanière et fiscale applicable aux équipements solaires"],"vigilance":["Qualité et garantie des batteries (durée de vie réelle)","Dimensionnement tenant compte de l'ensoleillement et des pertes (poussière, chaleur)","Maintenance après réception : prévoir un contrat ou un fonds dédié","Protection contre le vol et le vandalisme"]}$j$::jsonb FROM corps_metiers cm WHERE cm.code = 'ENERGIES_RENOUVELABLES'
