SELECT 'TDR-EQUIPEMENTS_BIOMEDICAUX', 'TDR', 'Termes de référence — Équipements biomédicaux et matériel médical', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser la structure bénéficiaire, son niveau de la pyramide sanitaire, les locaux d'installation et le personnel formé.","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Niveau et plateau technique de la structure","Locaux, énergie, climatisation et eau disponibles pour l'installation","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Doter [●] structures de santé d'équipements fonctionnels avant le [●].\n2. Assurer la maintenance préventive et curative pendant [●] ans.\n3. Former le personnel d'utilisation et de maintenance de premier niveau.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Doter [●] structures de santé d'équipements fonctionnels avant le [●].","Assurer la maintenance préventive et curative pendant [●] ans.","Former le personnel d'utilisation et de maintenance de premier niveau.","Un indicateur et une cible par objectif"],"exemple":"Doter [●] structures de santé d'équipements fonctionnels avant le [●].","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Spécifications techniques et quantités","obligatoire":true,"consigne":"Décrire chaque article ou lot : caractéristiques techniques minimales (avec « ou équivalent »), quantités et lieux de livraison.","contenu":"1. Équipements : caractéristiques techniques minimales (performance équivalente ou supérieure à [●]) : [●] unités\n2. Accessoires et consommables de démarrage pour [●] mois\n3. Aménagement des locaux et raccordements (électricité, fluides) : [●]\n4. Installation, calibrage et mise en service\n5. Formation des utilisateurs et des techniciens biomédicaux\n6. Contrat de maintenance préventive et curative avec délai d'intervention garanti\n7. Reprise et mise au rebut des équipements remplacés\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire chaque article ou lot : caractéristiques techniques minimales (avec « ou équivalent »), quantités et lieux de livraison.","points":["Équipements : caractéristiques techniques minimales (performance équivalente ou supérieure à [●]) : [●] unités","Accessoires et consommables de démarrage pour [●] mois","Aménagement des locaux et raccordements (électricité, fluides) : [●]","Installation, calibrage et mise en service","Formation des utilisateurs et des techniciens biomédicaux","Contrat de maintenance préventive et curative avec délai d'intervention garanti","Reprise et mise au rebut des équipements remplacés"],"exemple":"Équipements : caractéristiques techniques minimales (performance équivalente ou supérieure à [●]) : [●] unités","erreurs":["Prévoir l'énergie, la climatisation et le stabilisateur : cause fréquente de panne","Coût total de possession (consommables et maintenance) à comparer, pas seulement le prix d'achat","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Livraison, installation et documentation","obligatoire":true,"consigne":"Préciser les conditions de livraison, d'installation, de formation et la documentation fournie.","contenu":"L1 — Livraison, installation et mise en service sur site : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Procès-verbal d'installation et de calibrage : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — Manuels d'utilisation et de maintenance en français : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — Plan de maintenance préventive et rapports de formation : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Livraison, installation et mise en service sur site","Procès-verbal d'installation et de calibrage","Manuels d'utilisation et de maintenance en français","Plan de maintenance préventive et rapports de formation","Lien entre livrable et paiement"],"exemple":"Livraison, installation et mise en service sur site : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- Fabricant ou distributeur agréé avec service technique au Sénégal : [●]\n- Ingénieurs biomédicaux et techniciens certifiés : [●]\n- Stock de pièces détachées et de consommables : [●]\n- Références d'équipements similaires installés : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["Fabricant ou distributeur agréé avec service technique au Sénégal","Ingénieurs biomédicaux et techniciens certifiés","Stock de pièces détachées et de consommables","Références d'équipements similaires installés","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"Fabricant ou distributeur agréé avec service technique au Sénégal : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) des lieux de livraison : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Délai de préparation des locaux","Délai d'importation et de dédouanement"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Marquage de conformité et normes internationales équivalentes pour les dispositifs médicaux ; Enregistrement des dispositifs médicaux auprès de l'autorité nationale compétente (à confirmer).","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Marquage de conformité et normes internationales équivalentes pour les dispositifs médicaux","Références usuelles (à confirmer auprès de l'autorité compétente) : Enregistrement des dispositifs médicaux auprès de l'autorité nationale compétente (à confirmer)","Références usuelles (à confirmer auprès de l'autorité compétente) : Prescriptions de radioprotection pour l'imagerie (à confirmer)","Prévoir l'énergie, la climatisation et le stabilisateur : cause fréquente de panne","Coût total de possession (consommables et maintenance) à comparer, pas seulement le prix d'achat","Disponibilité des pièces sur dix ans","Équipements donateurs non standard : éviter"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Installation conforme et essais fonctionnels réussis\n- Calibrage et contrôle de sécurité électrique\n- Personnel formé attesté\n- Documentation complète remise\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Installation conforme et essais fonctionnels réussis","Calibrage et contrôle de sécurité électrique","Personnel formé attesté","Documentation complète remise","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Garanties, service après-vente et obligations du fournisseur","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"FOURNITURES","version":2,"questions":["Quels équipements, en quelle quantité et pour quelles structures ?","Les locaux, l'énergie et la climatisation sont-ils prêts ?","Quelle maintenance et quelle garantie sont exigées ?","Quel personnel sera formé ?","Quels consommables doivent être fournis au démarrage ?"],"references":["Marquage de conformité et normes internationales équivalentes pour les dispositifs médicaux","Enregistrement des dispositifs médicaux auprès de l'autorité nationale compétente (à confirmer)","Prescriptions de radioprotection pour l'imagerie (à confirmer)"],"vigilance":["Prévoir l'énergie, la climatisation et le stabilisateur : cause fréquente de panne","Coût total de possession (consommables et maintenance) à comparer, pas seulement le prix d'achat","Disponibilité des pièces sur dix ans","Équipements donateurs non standard : éviter"]}$j$::jsonb FROM corps_metiers cm WHERE cm.code = 'EQUIPEMENTS_BIOMEDICAUX'
