SELECT 'TDR-EQUIPEMENTS_SCOLAIRES', 'TDR', 'Termes de référence — Équipements scolaires et matériel pédagogique', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser les établissements bénéficiaires, les effectifs, les niveaux et le programme d'enseignement concerné.","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Établissements et effectifs d'élèves par niveau","Programme officiel et ressources pédagogiques existantes","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Doter [●] établissements d'équipements conformes aux standards avant la rentrée [●].\n2. Garantir la conformité des manuels aux programmes officiels.\n3. Livrer au plus près des établissements, y compris dans les zones difficiles d'accès.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Doter [●] établissements d'équipements conformes aux standards avant la rentrée [●].","Garantir la conformité des manuels aux programmes officiels.","Livrer au plus près des établissements, y compris dans les zones difficiles d'accès.","Un indicateur et une cible par objectif"],"exemple":"Doter [●] établissements d'équipements conformes aux standards avant la rentrée [●].","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Spécifications techniques et quantités","obligatoire":true,"consigne":"Décrire chaque article ou lot : caractéristiques techniques minimales (avec « ou équivalent »), quantités et lieux de livraison.","contenu":"1. Tables-bancs et mobilier : dimensions par niveau, matériaux, quantités [●]\n2. Manuels scolaires : titre, niveau, nombre de pages, tirage [●] exemplaires, conformes au programme\n3. Kits pédagogiques et matériel scientifique : [●]\n4. Équipement de bibliothèque ou de laboratoire : [●]\n5. Conditionnement, transport et livraison par établissement : [●]\n6. Remplacement des articles défectueux et pièces détachées\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire chaque article ou lot : caractéristiques techniques minimales (avec « ou équivalent »), quantités et lieux de livraison.","points":["Tables-bancs et mobilier : dimensions par niveau, matériaux, quantités [●]","Manuels scolaires : titre, niveau, nombre de pages, tirage [●] exemplaires, conformes au programme","Kits pédagogiques et matériel scientifique : [●]","Équipement de bibliothèque ou de laboratoire : [●]","Conditionnement, transport et livraison par établissement : [●]","Remplacement des articles défectueux et pièces détachées"],"exemple":"Tables-bancs et mobilier : dimensions par niveau, matériaux, quantités [●]","erreurs":["Livraison avant la rentrée scolaire : délai impératif","Taille du mobilier adaptée à l'âge","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Livraison, installation et documentation","obligatoire":true,"consigne":"Préciser les conditions de livraison, d'installation, de formation et la documentation fournie.","contenu":"L1 — Livraison par établissement avec bon de livraison signé : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Bon à tirer des manuels validé avant impression : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — Certificats de conformité du mobilier : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — État récapitulatif des livraisons par inspection : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Livraison par établissement avec bon de livraison signé","Bon à tirer des manuels validé avant impression","Certificats de conformité du mobilier","État récapitulatif des livraisons par inspection","Lien entre livrable et paiement"],"exemple":"Livraison par établissement avec bon de livraison signé : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- Fabricant ou imprimeur établi : [●]\n- Capacité de production dans les délais : [●]\n- Capacité de livraison dans toutes les régions : [●]\n- Références de fournitures scolaires pour des programmes publics : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["Fabricant ou imprimeur établi","Capacité de production dans les délais","Capacité de livraison dans toutes les régions","Références de fournitures scolaires pour des programmes publics","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"Fabricant ou imprimeur établi : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) des lieux de livraison : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Rentrée scolaire (date limite impérative)","Délai d'impression et de transport"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Programmes et manuels homologués par l'autorité en charge de l'éducation (à confirmer) ; Normes ergonomiques et de sécurité du mobilier scolaire.","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Programmes et manuels homologués par l'autorité en charge de l'éducation (à confirmer)","Références usuelles (à confirmer auprès de l'autorité compétente) : Normes ergonomiques et de sécurité du mobilier scolaire","Références usuelles (à confirmer auprès de l'autorité compétente) : Dépôt légal pour les ouvrages imprimés","Livraison avant la rentrée scolaire : délai impératif","Taille du mobilier adaptée à l'âge","Contrôle qualité du papier et de la reliure","Livraison jusqu'à l'établissement, pas seulement jusqu'à l'inspection"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Conformité des manuels au bon à tirer\n- Contrôle dimensionnel du mobilier\n- Quantités par établissement vérifiées\n- Réserves levées avant paiement\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Conformité des manuels au bon à tirer","Contrôle dimensionnel du mobilier","Quantités par établissement vérifiées","Réserves levées avant paiement","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Garanties, service après-vente et obligations du fournisseur","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"FOURNITURES","version":2,"questions":["Quels équipements ou manuels, pour quels niveaux et établissements ?","Quelles quantités et quelle date de livraison avant la rentrée ?","Livraison à l'inspection ou à l'établissement ?","Les manuels sont-ils homologués ?","Le marché est-il alloti par région ?"],"references":["Programmes et manuels homologués par l'autorité en charge de l'éducation (à confirmer)","Normes ergonomiques et de sécurité du mobilier scolaire","Dépôt légal pour les ouvrages imprimés"],"vigilance":["Livraison avant la rentrée scolaire : délai impératif","Taille du mobilier adaptée à l'âge","Contrôle qualité du papier et de la reliure","Livraison jusqu'à l'établissement, pas seulement jusqu'à l'inspection"]}$j$::jsonb FROM corps_metiers cm WHERE cm.code = 'EQUIPEMENTS_SCOLAIRES'
ON CONFLICT (code) DO UPDATE SET titre = EXCLUDED.titre, nature_marche = EXCLUDED.nature_marche, corps_metier_id = EXCLUDED.corps_metier_id, version = EXCLUDED.version, sections = EXCLUDED.sections, meta = EXCLUDED.meta;

