SELECT 'TDR-TEXTILES_UNIFORMES', 'TDR', 'Termes de référence — Textiles, uniformes et équipements individuels', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser les bénéficiaires, les tailles, la saison et les règles d'identification visuelle (logo, couleurs).","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Effectifs par taille et par type de tenue","Charte d'identification (couleurs, logos, étiquetage)","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Livrer [●] tenues conformes à la fiche technique et aux échantillons validés.\n2. Respecter la répartition par taille communiquée.\n3. Favoriser, à qualité égale, la production et la confection locales.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Livrer [●] tenues conformes à la fiche technique et aux échantillons validés.","Respecter la répartition par taille communiquée.","Favoriser, à qualité égale, la production et la confection locales.","Un indicateur et une cible par objectif"],"exemple":"Livrer [●] tenues conformes à la fiche technique et aux échantillons validés.","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Spécifications techniques et quantités","obligatoire":true,"consigne":"Décrire chaque article ou lot : caractéristiques techniques minimales (avec « ou équivalent »), quantités et lieux de livraison.","contenu":"1. Tenues : composition du tissu, grammage, solidité des couleurs, coutures : [●] unités par taille\n2. Chaussures et accessoires : [●] paires\n3. Équipements de protection individuelle (gants, casques, chasubles) : [●]\n4. Marquage, broderie ou logo selon la charte\n5. Conditionnement par taille et par bénéficiaire\n6. Livraison et retouches éventuelles\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire chaque article ou lot : caractéristiques techniques minimales (avec « ou équivalent »), quantités et lieux de livraison.","points":["Tenues : composition du tissu, grammage, solidité des couleurs, coutures : [●] unités par taille","Chaussures et accessoires : [●] paires","Équipements de protection individuelle (gants, casques, chasubles) : [●]","Marquage, broderie ou logo selon la charte","Conditionnement par taille et par bénéficiaire","Livraison et retouches éventuelles"],"exemple":"Tenues : composition du tissu, grammage, solidité des couleurs, coutures : [●] unités par taille","erreurs":["Échantillon validé = référence de réception","Répartition des tailles à vérifier avant production","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Livraison, installation et documentation","obligatoire":true,"consigne":"Préciser les conditions de livraison, d'installation, de formation et la documentation fournie.","contenu":"L1 — Échantillons à valider avant production : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Production et livraison par lots : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — Rapport de contrôle qualité par lot : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — Liste de remise par bénéficiaire : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Échantillons à valider avant production","Production et livraison par lots","Rapport de contrôle qualité par lot","Liste de remise par bénéficiaire","Lien entre livrable et paiement"],"exemple":"Échantillons à valider avant production : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- Atelier de confection disposant de la capacité nécessaire : [●]\n- Maîtrise de la qualité des tissus : [●]\n- Références de commandes comparables : [●]\n- Capacité de livraison dans les délais : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["Atelier de confection disposant de la capacité nécessaire","Maîtrise de la qualité des tissus","Références de commandes comparables","Capacité de livraison dans les délais","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"Atelier de confection disposant de la capacité nécessaire : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) des lieux de livraison : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Délai de validation des échantillons","Délai de production par lot"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Normes de qualité des textiles ou équivalentes ; Normes pour les équipements de protection individuelle (à confirmer).","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Normes de qualité des textiles ou équivalentes","Références usuelles (à confirmer auprès de l'autorité compétente) : Normes pour les équipements de protection individuelle (à confirmer)","Références usuelles (à confirmer auprès de l'autorité compétente) : Dispositifs de promotion de la production locale (à confirmer)","Échantillon validé = référence de réception","Répartition des tailles à vérifier avant production","Délai de confection élevé : planifier tôt","Contrôle du rétrécissement et de la solidité des teintures"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Conformité à l'échantillon validé\n- Contrôle par lot (coutures, dimensions, teintes)\n- Quantités par taille conformes\n- Retouches effectuées\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Conformité à l'échantillon validé","Contrôle par lot (coutures, dimensions, teintes)","Quantités par taille conformes","Retouches effectuées","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Garanties, service après-vente et obligations du fournisseur","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"FOURNITURES","version":2,"questions":["Quels types de tenues et quelles quantités par taille ?","Quels bénéficiaires et quels lieux de remise ?","Une charte graphique (logo, couleurs) existe-t-elle ?","Quelle date limite de livraison ?","Une préférence pour la confection locale est-elle prévue ?"],"references":["Normes de qualité des textiles ou équivalentes","Normes pour les équipements de protection individuelle (à confirmer)","Dispositifs de promotion de la production locale (à confirmer)"],"vigilance":["Échantillon validé = référence de réception","Répartition des tailles à vérifier avant production","Délai de confection élevé : planifier tôt","Contrôle du rétrécissement et de la solidité des teintures"]}$j$::jsonb FROM corps_m