SELECT 'TDR-CARBURANTS_LUBRIFIANTS', 'TDR', 'Termes de référence — Carburants, lubrifiants et énergie des flottes', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser la consommation annuelle, la flotte et les sites de distribution et de stockage.","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Consommation annuelle par type de carburant","Flotte concernée et lieux de ravitaillement","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Approvisionner l'autorité en carburants conformes aux spécifications nationales pendant [●] mois.\n2. Assurer le suivi des consommations par véhicule et par service.\n3. Garantir la continuité de l'approvisionnement sur l'ensemble du territoire concerné.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Approvisionner l'autorité en carburants conformes aux spécifications nationales pendant [●] mois.","Assurer le suivi des consommations par véhicule et par service.","Garantir la continuité de l'approvisionnement sur l'ensemble du territoire concerné.","Un indicateur et une cible par objectif"],"exemple":"Approvisionner l'autorité en carburants conformes aux spécifications nationales pendant [●] mois.","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Spécifications techniques et quantités","obligatoire":true,"consigne":"Décrire chaque article ou lot : caractéristiques techniques minimales (avec « ou équivalent »), quantités et lieux de livraison.","contenu":"1. Carburants : gasoil, essence, qualité, volume annuel estimé [●] litres\n2. Cartes de ravitaillement ou citernes sur site : [●]\n3. Lubrifiants et gaz : [●]\n4. Réseau de stations couvrant les zones d'intervention : [●]\n5. Plateforme de suivi des consommations et de facturation\n6. Prix : formule de révision liée au prix réglementé\n7. Reporting mensuel par véhicule et par service\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire chaque article ou lot : caractéristiques techniques minimales (avec « ou équivalent »), quantités et lieux de livraison.","points":["Carburants : gasoil, essence, qualité, volume annuel estimé [●] litres","Cartes de ravitaillement ou citernes sur site : [●]","Lubrifiants et gaz : [●]","Réseau de stations couvrant les zones d'intervention : [●]","Plateforme de suivi des consommations et de facturation","Prix : formule de révision liée au prix réglementé","Reporting mensuel par véhicule et par service"],"exemple":"Carburants : gasoil, essence, qualité, volume annuel estimé [●] litres","erreurs":["Prix réglementés : pas de marge sur le prix du produit mais sur les services","Contrôle des volumes et fraude aux cartes","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Livraison, installation et documentation","obligatoire":true,"consigne":"Préciser les conditions de livraison, d'installation, de formation et la documentation fournie.","contenu":"L1 — Cartes ou bons de ravitaillement remis : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Relevé mensuel des consommations : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — Facture mensuelle détaillée : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — Rapport annuel de consommation : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Cartes ou bons de ravitaillement remis","Relevé mensuel des consommations","Facture mensuelle détaillée","Rapport annuel de consommation","Lien entre livrable et paiement"],"exemple":"Cartes ou bons de ravitaillement remis : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- Distributeur titulaire des autorisations d'exercer : [●]\n- Réseau de stations ou capacité de livraison en vrac : [●]\n- Système de suivi des cartes : [●]\n- Références de fournitures à des flottes publiques : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["Distributeur titulaire des autorisations d'exercer","Réseau de stations ou capacité de livraison en vrac","Système de suivi des cartes","Références de fournitures à des flottes publiques","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"Distributeur titulaire des autorisations d'exercer : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) des lieux de livraison : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Durée du marché et reconduction éventuelle","Délai de livraison en vrac"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Réglementation du secteur des hydrocarbures et prix réglementés (à confirmer) ; Spécifications nationales des carburants.","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Réglementation du secteur des hydrocarbures et prix réglementés (à confirmer)","Références usuelles (à confirmer auprès de l'autorité compétente) : Spécifications nationales des carburants","Références usuelles (à confirmer auprès de l'autorité compétente) : Normes de sécurité de stockage et de transport","Prix réglementés : pas de marge sur le prix du produit mais sur les services","Contrôle des volumes et fraude aux cartes","Garantie de continuité en cas de pénurie","Éviter la dépendance à un seul réseau de stations"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Contrôle des volumes livrés\n- Contrôle de la qualité du produit sur échantillon\n- Rapprochement mensuel des consommations et des factures\n- Disponibilité du service sur les zones prévues\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Contrôle des volumes livrés","Contrôle de la qualité du produit sur échantillon","Rapprochement mensuel des consommations et des factures","Disponibilité du service sur les zones prévues","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Garanties, service après-vente et obligations du fournisseur","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"FOURNITURES","version":2,"questions":["Quels carburants et quels volumes annuels ?","Livraison en vrac, par cartes ou les deux ?","Quelles zones et quels sites doivent être couverts ?","Quel suivi des consommations est attendu ?","Quelle durée de contrat ?"],"references":["Réglementation du secteur des hydrocarbures et prix réglementés (à confirmer)","Spécifications nationales des carburants","Normes de sécurité de stockage et de transport"],"vigilance":["Prix réglementés : pas de marge sur le prix du produit mais sur les services","Contrôle des volumes et fraude aux cartes","Garantie de continuité en cas de pénurie","Éviter la dépendance à un seul réseau de stations"]}$j$::jsonb FROM corps_metiers cm WHERE cm.code = 'CARBURANTS_LUBRIFIANTS'
