SELECT 'TDR-PECHE_AQUACULTURE', 'TDR', 'Termes de référence — Pêche, aquaculture et économie maritime', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser le site, la pêcherie concernée, les acteurs (pêcheurs, mareyeurs, transformatrices) et les enjeux de ressource.","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Pêcherie ou filière et acteurs concernés","État de la ressource et mesures de gestion en vigueur","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Appuyer [●] acteurs de la filière [●] pour améliorer la qualité et la valeur ajoutée.\n2. Contribuer à la gestion durable de la ressource.\n3. Améliorer les conditions de sécurité et d'hygiène sur [●] sites de débarquement.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Appuyer [●] acteurs de la filière [●] pour améliorer la qualité et la valeur ajoutée.","Contribuer à la gestion durable de la ressource.","Améliorer les conditions de sécurité et d'hygiène sur [●] sites de débarquement.","Un indicateur et une cible par objectif"],"exemple":"Appuyer [●] acteurs de la filière [●] pour améliorer la qualité et la valeur ajoutée.","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Consistance des prestations et méthodologie","obligatoire":true,"consigne":"Décrire sans ambiguïté les prestations attendues, leur étendue chiffrée et la méthodologie exigée.","contenu":"1. Diagnostic de la filière et des sites : [●]\n2. Formation en hygiène, qualité, sécurité en mer : [●] sessions\n3. Appui à la transformation et à la conservation (fumage, séchage, froid) : [●]\n4. Équipements collectifs (chambres froides, fabriques de glace) : [●]\n5. Suivi des captures et de la ressource avec les services compétents\n6. Structuration des organisations professionnelles\n7. Rapport de capitalisation\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire sans ambiguïté les prestations attendues, leur étendue chiffrée et la méthodologie exigée.","points":["Diagnostic de la filière et des sites : [●]","Formation en hygiène, qualité, sécurité en mer : [●] sessions","Appui à la transformation et à la conservation (fumage, séchage, froid) : [●]","Équipements collectifs (chambres froides, fabriques de glace) : [●]","Suivi des captures et de la ressource avec les services compétents","Structuration des organisations professionnelles","Rapport de capitalisation"],"exemple":"Diagnostic de la filière et des sites : [●]","erreurs":["Ne pas augmenter l'effort de pêche sur des stocks fragiles","Hygiène et chaîne du froid pour la valeur ajoutée","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Livrables et calendrier","obligatoire":true,"consigne":"Lister chaque livrable, son format, son échéance et son critère d'acceptation.","contenu":"L1 — Diagnostic validé et plan d'action : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Rapports de formation avec listes de présence : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — Rapports de suivi des sites et des équipements : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — Rapport final : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Diagnostic validé et plan d'action","Rapports de formation avec listes de présence","Rapports de suivi des sites et des équipements","Rapport final","Lien entre livrable et paiement"],"exemple":"Diagnostic validé et plan d'action : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- Bureau ou ONG expérimenté dans la pêche artisanale : [●]\n- Spécialiste halieutique et qualité des produits : [●]\n- Animateurs maîtrisant les langues locales : [●]\n- Références d'appui à des acteurs de la pêche : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["Bureau ou ONG expérimenté dans la pêche artisanale","Spécialiste halieutique et qualité des produits","Animateurs maîtrisant les langues locales","Références d'appui à des acteurs de la pêche","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"Bureau ou ONG expérimenté dans la pêche artisanale : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) d'exécution : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Saisons de pêche et repos biologique","Disponibilité des acteurs"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Code de la pêche et mesures de gestion de la ressource (à confirmer avec la direction technique compétente) ; Normes sanitaires des produits de la pêche pour l'export (à confirmer).","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Code de la pêche et mesures de gestion de la ressource (à confirmer avec la direction technique compétente)","Références usuelles (à confirmer auprès de l'autorité compétente) : Normes sanitaires des produits de la pêche pour l'export (à confirmer)","Références usuelles (à confirmer auprès de l'autorité compétente) : Réglementation sur la sécurité en mer","Ne pas augmenter l'effort de pêche sur des stocks fragiles","Hygiène et chaîne du froid pour la valeur ajoutée","Implication des femmes transformatrices","Entretien des équipements collectifs après remise"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Activités réalisées conformes au plan\n- Équipements fonctionnels et remis aux bénéficiaires\n- Bénéficiaires formés attestés\n- Rapports validés\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Activités réalisées conformes au plan","Équipements fonctionnels et remis aux bénéficiaires","Bénéficiaires formés attestés","Rapports validés","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Obligations des parties, confidentialité et propriété intellectuelle","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"SERVICES","version":2,"questions":["Quelle filière, quel site et quels acteurs ?","Quelles activités (formation, équipement, transformation) ?","Quels objectifs chiffrés ?","Quelles mesures de gestion de la ressource s'appliquent ?","Qui entretiendra les équipements ?"],"references":["Code de la pêche et mesures de gestion de la ressource (à confirmer avec la direction technique compétente)","Normes sanitaires des produits de la pêche pour l'export (à confirmer)","Réglementation sur la sécurité en mer"],"vigilance":["Ne pas augmenter l'effort de pêche sur des stocks fragiles","Hygiène et chaîne du froid pour la valeur ajoutée","Implication des femmes transformatrices","Entretien des équipements collectifs après remise"]}$j$::jsonb FROM corps_metiers cm WHERE cm.code = 'PECHE_AQUACULTURE'
