SELECT 'TDR-DEVELOPPEMENT_COMMUNAUTAIRE', 'TDR', 'Termes de référence — Développement communautaire et action sociale', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser la zone, les populations cibles, les vulnérabilités ciblées et le cadre institutionnel.","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Populations cibles et critères de ciblage","Dispositif institutionnel local (communes, comités)","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Atteindre [●] bénéficiaires dont [●] % de femmes et de jeunes.\n2. Renforcer les capacités des organisations communautaires.\n3. Contribuer à l'amélioration durable des conditions de vie.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Atteindre [●] bénéficiaires dont [●] % de femmes et de jeunes.","Renforcer les capacités des organisations communautaires.","Contribuer à l'amélioration durable des conditions de vie.","Un indicateur et une cible par objectif"],"exemple":"Atteindre [●] bénéficiaires dont [●] % de femmes et de jeunes.","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Consistance des prestations et méthodologie","obligatoire":true,"consigne":"Décrire sans ambiguïté les prestations attendues, leur étendue chiffrée et la méthodologie exigée.","contenu":"1. Ciblage et enregistrement des bénéficiaires : [●]\n2. Sensibilisation et mobilisation communautaire : [●] séances\n3. Formation et accompagnement des organisations : [●]\n4. Appui aux activités génératrices de revenus : [●]\n5. Mécanisme de gestion des plaintes accessible\n6. Suivi de proximité et collecte de données désagrégées\n7. Rapport d'impact\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire sans ambiguïté les prestations attendues, leur étendue chiffrée et la méthodologie exigée.","points":["Ciblage et enregistrement des bénéficiaires : [●]","Sensibilisation et mobilisation communautaire : [●] séances","Formation et accompagnement des organisations : [●]","Appui aux activités génératrices de revenus : [●]","Mécanisme de gestion des plaintes accessible","Suivi de proximité et collecte de données désagrégées","Rapport d'impact"],"exemple":"Ciblage et enregistrement des bénéficiaires : [●]","erreurs":["Ciblage transparent et vérifiable pour éviter le clientélisme","Protection des données personnelles des bénéficiaires","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Livrables et calendrier","obligatoire":true,"consigne":"Lister chaque livrable, son format, son échéance et son critère d'acceptation.","contenu":"L1 — Plan de mise en œuvre validé : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Liste certifiée des bénéficiaires : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — Rapports trimestriels : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — Rapport final d'impact : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Plan de mise en œuvre validé","Liste certifiée des bénéficiaires","Rapports trimestriels","Rapport final d'impact","Lien entre livrable et paiement"],"exemple":"Plan de mise en œuvre validé : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- ONG ou structure d'appui reconnue : [●]\n- Équipe pluridisciplinaire (social, genre, agronomie) : [●]\n- Animateurs maîtrisant les langues locales : [●]\n- Références de projets communautaires : [●]\n- Gestion financière transparente : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["ONG ou structure d'appui reconnue","Équipe pluridisciplinaire (social, genre, agronomie)","Animateurs maîtrisant les langues locales","Références de projets communautaires","Gestion financière transparente","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"ONG ou structure d'appui reconnue : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) d'exécution : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Calendrier de mise en œuvre","Périodes de forte activité agricole"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Cadre de protection sociale et du ciblage (à confirmer) ; Code de conduite et protection contre les abus.","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Cadre de protection sociale et du ciblage (à confirmer)","Références usuelles (à confirmer auprès de l'autorité compétente) : Code de conduite et protection contre les abus","Références usuelles (à confirmer auprès de l'autorité compétente) : Exigences d'inclusion et de genre","Ciblage transparent et vérifiable pour éviter le clientélisme","Protection des données personnelles des bénéficiaires","Mécanisme de plainte opérationnel","Durabilité après la fin du financement"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Bénéficiaires vérifiés sur échantillon\n- Activités réalisées conformes au plan\n- Rapports validés\n- Plaintes traitées dans les délais\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Bénéficiaires vérifiés sur échantillon","Activités réalisées conformes au plan","Rapports validés","Plaintes traitées dans les délais","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Obligations des parties, confidentialité et propriété intellectuelle","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"SERVICES","version":2,"questions":["Quelle zone, quelle population et quels critères de ciblage ?","Quelles activités attendues ?","Quels objectifs chiffrés ?","Quel mécanisme de plaintes ?","Comment assurer la durabilité ?"],"references":["Cadre de protection sociale et du ciblage (à confirmer)","Code de conduite et protection contre les abus","Exigences d'inclusion et de genre"],"vigilance":["Ciblage transparent et vérifiable pour éviter le clientélisme","Protection des données personnelles des bénéficiaires","Mécanisme de plainte opérationnel","Durabilité après la fin du financement"]}$j$::jsonb FROM corps_metiers cm WHERE cm.code = 'DEVELOPPEMENT_COMMUNAUTAIRE'
