SELECT 'TDR-TOURISME_CULTURE_SPORT', 'TDR', 'Termes de référence — Tourisme, culture, sport et événements', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser l'événement ou le programme, le public, les lieux, les dates et les partenaires.","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Public attendu et fréquentation","Lieux, dates et partenaires institutionnels","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Organiser [●] avec [●] participants dans les conditions de sécurité requises.\n2. Assurer la visibilité de l'événement et son accessibilité.\n3. Valoriser le patrimoine ou les talents locaux.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Organiser [●] avec [●] participants dans les conditions de sécurité requises.","Assurer la visibilité de l'événement et son accessibilité.","Valoriser le patrimoine ou les talents locaux.","Un indicateur et une cible par objectif"],"exemple":"Organiser [●] avec [●] participants dans les conditions de sécurité requises.","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Consistance des prestations et méthodologie","obligatoire":true,"consigne":"Décrire sans ambiguïté les prestations attendues, leur étendue chiffrée et la méthodologie exigée.","contenu":"1. Conception du programme et de la direction artistique ou sportive : [●]\n2. Logistique, scène, sonorisation, éclairage, tentes : [●]\n3. Sécurité, secours et plan d'évacuation : [●]\n4. Accueil, billetterie et signalétique : [●]\n5. Promotion et communication : [●]\n6. Restauration et hébergement des invités : [●]\n7. Bilan de l'événement et fréquentation\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire sans ambiguïté les prestations attendues, leur étendue chiffrée et la méthodologie exigée.","points":["Conception du programme et de la direction artistique ou sportive : [●]","Logistique, scène, sonorisation, éclairage, tentes : [●]","Sécurité, secours et plan d'évacuation : [●]","Accueil, billetterie et signalétique : [●]","Promotion et communication : [●]","Restauration et hébergement des invités : [●]","Bilan de l'événement et fréquentation"],"exemple":"Conception du programme et de la direction artistique ou sportive : [●]","erreurs":["Plan de sécurité et de secours obligatoire","Autorisations à obtenir bien avant la date","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Livrables et calendrier","obligatoire":true,"consigne":"Lister chaque livrable, son format, son échéance et son critère d'acceptation.","contenu":"L1 — Programme détaillé et planning logistique : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Plan de sécurité validé par les autorités : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — Compte rendu quotidien : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — Bilan final avec chiffres de fréquentation : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Programme détaillé et planning logistique","Plan de sécurité validé par les autorités","Compte rendu quotidien","Bilan final avec chiffres de fréquentation","Lien entre livrable et paiement"],"exemple":"Programme détaillé et planning logistique : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- Organisateur ayant des références d'événements comparables : [●]\n- Responsable sécurité et secours : [●]\n- Prestataires techniques qualifiés : [●]\n- Assurance responsabilité civile : [●]\n- Maîtrise des autorisations d'événement : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["Organisateur ayant des références d'événements comparables","Responsable sécurité et secours","Prestataires techniques qualifiés","Assurance responsabilité civile","Maîtrise des autorisations d'événement","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"Organisateur ayant des références d'événements comparables : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) d'exécution : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Dates fixes de l'événement","Délais de montage et démontage"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Autorisations de manifestation et de rassemblement (à confirmer) ; Règles de sécurité des établissements recevant du public.","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Autorisations de manifestation et de rassemblement (à confirmer)","Références usuelles (à confirmer auprès de l'autorité compétente) : Règles de sécurité des établissements recevant du public","Références usuelles (à confirmer auprès de l'autorité compétente) : Droits d'auteur et de diffusion","Plan de sécurité et de secours obligatoire","Autorisations à obtenir bien avant la date","Prévoir un plan B en cas d'intempéries","Respect des droits d'auteur"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Prestations réalisées conformes au programme\n- Plan de sécurité appliqué\n- Bilan et justificatifs remis\n- Absence d'incident majeur non traité\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Prestations réalisées conformes au programme","Plan de sécurité appliqué","Bilan et justificatifs remis","Absence d'incident majeur non traité","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Obligations des parties, confidentialité et propriété intellectuelle","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"SERVICES","version":2,"questions":["Quel événement, quel public et quelles dates ?","Quels lieux et quelles installations ?","Quels besoins techniques et de sécurité ?","Quels partenaires ou autorisations ?","Quel bilan est attendu ?"],"references":["Autorisations de manifestation et de rassemblement (à confirmer)","Règles de sécurité des établissements recevant du public","Droits d'auteur et de diffusion"],"vigilance":["Plan de sécurité et de secours obligatoire","Autorisations à obtenir bien avant la date","Prévoir un plan B en cas d'intempéries","Respect des droits d'auteur"]}$j$::jsonb FROM corps_metiers cm WHERE cm.code = 'TOURISME_CULTURE_SPORT'
