SELECT 'TDR-ETUDES_ENVIRONNEMENTALES_SOCIALES', 'TDR', 'Termes de référence — Études d''impact environnemental et social', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser le projet, sa catégorie, la zone d'influence et les exigences du bailleur éventuel.","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Description du projet et zone d'influence","Exigences réglementaires et du bailleur (sauvegardes)","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Identifier et évaluer les impacts environnementaux et sociaux du projet [●].\n2. Proposer un plan de gestion environnementale et sociale (PGES) chiffré.\n3. Obtenir la validation réglementaire de l'étude avant le démarrage des travaux.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Identifier et évaluer les impacts environnementaux et sociaux du projet [●].","Proposer un plan de gestion environnementale et sociale (PGES) chiffré.","Obtenir la validation réglementaire de l'étude avant le démarrage des travaux.","Un indicateur et une cible par objectif"],"exemple":"Identifier et évaluer les impacts environnementaux et sociaux du projet [●].","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Consistance des prestations et méthodologie","obligatoire":true,"consigne":"Décrire sans ambiguïté les prestations attendues, leur étendue chiffrée et la méthodologie exigée.","contenu":"1. Cadrage et consultation du public : [●] séances\n2. État initial (milieu physique, biologique, humain) : [●]\n3. Analyse des alternatives et des impacts : [●]\n4. Plan de gestion environnementale et sociale avec coûts et responsabilités\n5. Plan d'action de réinstallation si nécessaire : [●]\n6. Rapport pour validation réglementaire et audiences publiques\n7. Appui à la validation par l'autorité compétente\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire sans ambiguïté les prestations attendues, leur étendue chiffrée et la méthodologie exigée.","points":["Cadrage et consultation du public : [●] séances","État initial (milieu physique, biologique, humain) : [●]","Analyse des alternatives et des impacts : [●]","Plan de gestion environnementale et sociale avec coûts et responsabilités","Plan d'action de réinstallation si nécessaire : [●]","Rapport pour validation réglementaire et audiences publiques","Appui à la validation par l'autorité compétente"],"exemple":"Cadrage et consultation du public : [●] séances","erreurs":["Consultation publique réelle, avec compte rendu","PGES budgétisé et réaliste","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Livrables et calendrier","obligatoire":true,"consigne":"Lister chaque livrable, son format, son échéance et son critère d'acceptation.","contenu":"L1 — Note de cadrage validée : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Rapport provisoire d'étude d'impact : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — PGES et budget associé : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — Rapport final validé et rapport de consultation publique : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Note de cadrage validée","Rapport provisoire d'étude d'impact","PGES et budget associé","Rapport final validé et rapport de consultation publique","Lien entre livrable et paiement"],"exemple":"Note de cadrage validée : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- Bureau agréé pour la réalisation d'études d'impact : [●]\n- Chef de mission environnementaliste confirmé : [●]\n- Sociologue / spécialiste des réinstallations : [●]\n- Spécialistes biodiversité, eau, bruit selon le projet : [●]\n- Références d'études comparables : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["Bureau agréé pour la réalisation d'études d'impact","Chef de mission environnementaliste confirmé","Sociologue / spécialiste des réinstallations","Spécialistes biodiversité, eau, bruit selon le projet","Références d'études comparables","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"Bureau agréé pour la réalisation d'études d'impact : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) d'exécution : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Délai de validation par l'autorité","Saison sèche ou humide pour l'état initial"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Code de l'environnement et procédure d'étude d'impact (à confirmer auprès de la DEEC) ; Agrément des bureaux pour les études d'impact (à confirmer).","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Code de l'environnement et procédure d'étude d'impact (à confirmer auprès de la DEEC)","Références usuelles (à confirmer auprès de l'autorité compétente) : Agrément des bureaux pour les études d'impact (à confirmer)","Références usuelles (à confirmer auprès de l'autorité compétente) : Politiques de sauvegarde du bailleur le cas échéant","Consultation publique réelle, avec compte rendu","PGES budgétisé et réaliste","Indépendance du bureau vis-à-vis du maître d'ouvrage","Délais de validation réglementaire"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Rapport conforme au plan réglementaire\n- Validation par l'autorité compétente obtenue\n- Consultation publique tenue et documentée\n- PGES exploitable par l'entreprise\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Rapport conforme au plan réglementaire","Validation par l'autorité compétente obtenue","Consultation publique tenue et documentée","PGES exploitable par l'entreprise","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Obligations des parties, confidentialité et propriété intellectuelle","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"SERVICES","version":2,"questions":["Quel projet et quelle zone d'influence ?","Quelles exigences réglementaires et du bailleur ?","Un déplacement de populations est-il prévu ?","Quels risques environnementaux majeurs ?","Quel calendrier de validation ?"],"references":["Code de l'environnement et procédure d'étude d'impact (à confirmer auprès de la DEEC)","Agrément des bureaux pour les études d'impact (à confirmer)","Politiques de sauvegarde du bailleur le cas échéant"],"vigilance":["Consultation publique réelle, avec compte rendu","PGES budgétisé et réaliste","Indépendance du bureau vis-à-vis du maître d'ouvrage","Délais de validation réglementaire"]}$j$::jsonb FROM corps_metiers cm WHERE cm.code = 'ETUDES_ENVIRONNEMENTALES_SOCIALES'
