SELECT 'TDR-AUDIT_FINANCES', 'TDR', 'Termes de référence — Audit financier, comptable et organisationnel', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser l'entité ou le programme audité, la période et le cadre d'audit exigé.","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Entité, période et périmètre de l'audit","Référentiel comptable et normes d'audit applicables","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Exprimer une opinion sur les états financiers de l'exercice [●].\n2. Évaluer le dispositif de contrôle interne et la conformité aux procédures.\n3. Formuler des recommandations hiérarchisées avec un plan d'action.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Exprimer une opinion sur les états financiers de l'exercice [●].","Évaluer le dispositif de contrôle interne et la conformité aux procédures.","Formuler des recommandations hiérarchisées avec un plan d'action.","Un indicateur et une cible par objectif"],"exemple":"Exprimer une opinion sur les états financiers de l'exercice [●].","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Consistance des prestations et méthodologie","obligatoire":true,"consigne":"Décrire sans ambiguïté les prestations attendues, leur étendue chiffrée et la méthodologie exigée.","contenu":"1. Planification et prise de connaissance de l'entité : [●]\n2. Revue du contrôle interne et tests de procédures\n3. Contrôles substantifs sur les comptes : [●]\n4. Revue de conformité (marchés publics, passation, exécution) : [●] marchés\n5. Lettre de recommandations (management letter)\n6. Restitution à la direction et aux organes de gouvernance\n7. Suivi de la mise en œuvre des recommandations précédentes\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire sans ambiguïté les prestations attendues, leur étendue chiffrée et la méthodologie exigée.","points":["Planification et prise de connaissance de l'entité : [●]","Revue du contrôle interne et tests de procédures","Contrôles substantifs sur les comptes : [●]","Revue de conformité (marchés publics, passation, exécution) : [●] marchés","Lettre de recommandations (management letter)","Restitution à la direction et aux organes de gouvernance","Suivi de la mise en œuvre des recommandations précédentes"],"exemple":"Planification et prise de connaissance de l'entité : [●]","erreurs":["Indépendance : aucune mission de conseil conflictuelle","Accès aux documents et au personnel garanti par l'autorité","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Livrables et calendrier","obligatoire":true,"consigne":"Lister chaque livrable, son format, son échéance et son critère d'acceptation.","contenu":"L1 — Plan de mission validé : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Rapport provisoire contradictoire : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — Rapport d'audit et opinion : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — Lettre de recommandations et plan d'action : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Plan de mission validé","Rapport provisoire contradictoire","Rapport d'audit et opinion","Lettre de recommandations et plan d'action","Lien entre livrable et paiement"],"exemple":"Plan de mission validé : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- Cabinet inscrit à l'ordre des experts comptables : [●]\n- Associé signataire expérimenté : [●]\n- Auditeurs seniors et juniors : [●]\n- Références d'audits d'entités publiques ou de projets : [●]\n- Indépendance attestée : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["Cabinet inscrit à l'ordre des experts comptables","Associé signataire expérimenté","Auditeurs seniors et juniors","Références d'audits d'entités publiques ou de projets","Indépendance attestée","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"Cabinet inscrit à l'ordre des experts comptables : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) d'exécution : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Dates de clôture des comptes","Délais de la procédure contradictoire"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Normes internationales d'audit et référentiel comptable applicable (à confirmer) ; Cadre OHADA et plan comptable applicable (à confirmer).","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Normes internationales d'audit et référentiel comptable applicable (à confirmer)","Références usuelles (à confirmer auprès de l'autorité compétente) : Cadre OHADA et plan comptable applicable (à confirmer)","Références usuelles (à confirmer auprès de l'autorité compétente) : Contrôle de la Cour des comptes et des corps de contrôle","Indépendance : aucune mission de conseil conflictuelle","Accès aux documents et au personnel garanti par l'autorité","Procédure contradictoire avant le rapport final","Confidentialité des informations"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Rapport conforme aux normes d'audit\n- Opinion argumentée et documentée\n- Recommandations hiérarchisées\n- Restitution tenue\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Rapport conforme aux normes d'audit","Opinion argumentée et documentée","Recommandations hiérarchisées","Restitution tenue","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Obligations des parties, confidentialité et propriété intellectuelle","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"SERVICES","version":2,"questions":["Quelle entité, quelle période et quel type d'audit ?","Quel référentiel comptable ?","Faut-il aussi une revue de conformité des marchés ?","Quelle date de rapport final ?","Des audits précédents existent-ils ?"],"references":["Normes internationales d'audit et référentiel comptable applicable (à confirmer)","Cadre OHADA et plan comptable applicable (à confirmer)","Contrôle de la Cour des comptes et des corps de contrôle"],"vigilance":["Indépendance : aucune mission de conseil conflictuelle","Accès aux documents et au personnel garanti par l'autorité","Procédure contradictoire avant le rapport final","Confidentialité des informations"]}$j$::jsonb FROM corps_metiers cm WHERE cm.code = 'AUDIT_FINANCES'
