SELECT 'TDR-TOPOGRAPHIE_SIG', 'TDR', 'Termes de référence — Topographie, cartographie et systèmes d''information géographique', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser la zone, l'échelle, la précision requise et l'usage des données produites.","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Emprise, échelle et précision","Usage prévu (aménagement, cadastre, planification)","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Produire les levés et la cartographie de [●] hectares / [●] km à la précision de [●] cm.\n2. Livrer des données SIG géoréférencées documentées.\n3. Former les agents de l'institution à leur exploitation.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Produire les levés et la cartographie de [●] hectares / [●] km à la précision de [●] cm.","Livrer des données SIG géoréférencées documentées.","Former les agents de l'institution à leur exploitation.","Un indicateur et une cible par objectif"],"exemple":"Produire les levés et la cartographie de [●] hectares / [●] km à la précision de [●] cm.","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Consistance des prestations et méthodologie","obligatoire":true,"consigne":"Décrire sans ambiguïté les prestations attendues, leur étendue chiffrée et la méthodologie exigée.","contenu":"1. Implantation du canevas et rattachement au système géodésique national : [●]\n2. Levés topographiques ou par drone : [●] ha\n3. Traitement, restitution et production des plans et cartes : [●]\n4. Base de données SIG avec métadonnées : [●] couches\n5. Contrôles de précision et rapport de qualité\n6. Remise des données brutes et traitées\n7. Formation à l'exploitation du SIG\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire sans ambiguïté les prestations attendues, leur étendue chiffrée et la méthodologie exigée.","points":["Implantation du canevas et rattachement au système géodésique national : [●]","Levés topographiques ou par drone : [●] ha","Traitement, restitution et production des plans et cartes : [●]","Base de données SIG avec métadonnées : [●] couches","Contrôles de précision et rapport de qualité","Remise des données brutes et traitées","Formation à l'exploitation du SIG"],"exemple":"Implantation du canevas et rattachement au système géodésique national : [●]","erreurs":["Étalonnage des instruments attesté","Autorisation de vol de drone avant tout levé","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Livrables et calendrier","obligatoire":true,"consigne":"Lister chaque livrable, son format, son échéance et son critère d'acceptation.","contenu":"L1 — Rapport de canevas et de précision : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Plans et cartes aux formats convenus : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — Base de données SIG documentée : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — Rapport de formation : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Rapport de canevas et de précision","Plans et cartes aux formats convenus","Base de données SIG documentée","Rapport de formation","Lien entre livrable et paiement"],"exemple":"Rapport de canevas et de précision : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- Géomètre-expert ou ingénieur géomètre : [●]\n- Opérateurs topographes et pilotes de drone autorisés : [●]\n- Matériel (stations, GNSS, drone) étalonné : [●]\n- Références de levés comparables : [●]\n- Logiciels de traitement et SIG : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["Géomètre-expert ou ingénieur géomètre","Opérateurs topographes et pilotes de drone autorisés","Matériel (stations, GNSS, drone) étalonné","Références de levés comparables","Logiciels de traitement et SIG","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"Géomètre-expert ou ingénieur géomètre : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) d'exécution : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Conditions météorologiques","Délais de traitement"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Système géodésique national de référence (à confirmer) ; Autorisation d'utilisation de drones auprès de l'autorité compétente (à confirmer).","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Système géodésique national de référence (à confirmer)","Références usuelles (à confirmer auprès de l'autorité compétente) : Autorisation d'utilisation de drones auprès de l'autorité compétente (à confirmer)","Références usuelles (à confirmer auprès de l'autorité compétente) : Réglementation du cadastre et de la publicité foncière","Étalonnage des instruments attesté","Autorisation de vol de drone avant tout levé","Livraison des données brutes en plus des produits","Formats ouverts et métadonnées"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Contrôle de précision sur points témoins\n- Plans conformes aux normes de représentation\n- Base SIG complète\n- Formation réalisée\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Contrôle de précision sur points témoins","Plans conformes aux normes de représentation","Base SIG complète","Formation réalisée","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Obligations des parties, confidentialité et propriété intellectuelle","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"SERVICES","version":2,"questions":["Quelle emprise et quelle échelle ?","Quelle précision est exigée ?","Quels formats de données ?","Un survol par drone est-il envisagé ?","Qui exploitera le SIG ?"],"references":["Système géodésique national de référence (à confirmer)","Autorisation d'utilisation de drones auprès de l'autorité compétente (à confirmer)","Réglementation du cadastre et de la publicité foncière"],"vigilance":["Étalonnage des instruments attesté","Autorisation de vol de drone avant tout levé","Livraison des données brutes en plus des produits","Formats ouverts et métadonnées"]}$j$::jsonb FROM corps_metiers cm WHERE cm.code = 'TOPOGRAPHIE_SIG'
