SELECT 'TDR-AMO_GESTION_PROJET', 'TDR', 'Termes de référence — Assistance à maîtrise d''ouvrage et gestion de projet', NULL, cm.id, 2, $j$[{"id":"contexte","titre":"1. Contexte et justification","obligatoire":true,"consigne":"Présenter le cadre institutionnel, le besoin et sa justification. Préciser le projet ou programme, son financement, ses composantes et l'organisation de la maîtrise d'ouvrage.","contenu":"{{autorite}} conduit le projet « {{intitule}} » (réf. {{reference}}), financé sur la ligne {{ligne_budgetaire}} de l'exercice {{annee}}.\n\nBesoin exprimé : {{besoin}}\n\nJustification : {{justification}}","guide":{"objectif":"Expliquer pourquoi ce marché existe, en une page, pour que tout candidat comprenne l'enjeu.","points":["Mission de l'autorité et lien avec la politique sectorielle","Situation actuelle chiffrée et problème à résoudre","Composantes, budget et calendrier du programme","Organisation de la maîtrise d'ouvrage et rôle de l'assistant","Financement (ligne budgétaire, bailleur éventuel)"],"exemple":"Le service [●] constate [problème chiffré]. Le présent marché vise à [résultat attendu] au bénéfice de [bénéficiaires], dans [zone géographique].","erreurs":["Copier l'historique de l'institution sans lien avec le besoin","Omettre le financement ou les bénéficiaires","Justifier par l'urgence sans date ni fait"]}},{"id":"objectifs","titre":"2. Objectifs","obligatoire":true,"consigne":"Un objectif général et des objectifs spécifiques mesurables.","contenu":"Objectif général : [●]\n\nObjectifs spécifiques :\n1. Appuyer l'autorité dans la planification, la passation et le suivi du projet [●].\n2. Respecter les délais, les coûts et les règles fiduciaires.\n3. Renforcer durablement les capacités de l'équipe de l'institution.","guide":{"objectif":"Fixer des objectifs vérifiables à la réception ; chacun a un indicateur et une cible.","points":["Un objectif général (une phrase)","Appuyer l'autorité dans la planification, la passation et le suivi du projet [●].","Respecter les délais, les coûts et les règles fiduciaires.","Renforcer durablement les capacités de l'équipe de l'institution.","Un indicateur et une cible par objectif"],"exemple":"Appuyer l'autorité dans la planification, la passation et le suivi du projet [●].","erreurs":["Objectifs non mesurables (« améliorer la qualité »)","Confondre objectifs et moyens","Plus de cinq objectifs"]}},{"id":"consistance","titre":"3. Consistance des prestations et méthodologie","obligatoire":true,"consigne":"Décrire sans ambiguïté les prestations attendues, leur étendue chiffrée et la méthodologie exigée.","contenu":"1. Planification et plan de passation des marchés : [●]\n2. Appui à la préparation des dossiers et à la passation : [●] marchés\n3. Suivi budgétaire et financier, reporting aux bailleurs : [●]\n4. Gestion des risques et suivi du calendrier\n5. Suivi des contrats et des paiements\n6. Rapports d'avancement périodiques\n7. Transfert de compétences et formation de l'équipe\n\nExclusions du marché : [●]","guide":{"objectif":"Décrire sans ambiguïté les prestations attendues, leur étendue chiffrée et la méthodologie exigée.","points":["Planification et plan de passation des marchés : [●]","Appui à la préparation des dossiers et à la passation : [●] marchés","Suivi budgétaire et financier, reporting aux bailleurs : [●]","Gestion des risques et suivi du calendrier","Suivi des contrats et des paiements","Rapports d'avancement périodiques","Transfert de compétences et formation de l'équipe"],"exemple":"Planification et plan de passation des marchés : [●]","erreurs":["L'assistant conseille, l'autorité décide","Éviter la substitution durable à l'équipe de l'autorité","Quantités « environ » ou « selon besoin »","Marque ou référence commerciale sans « ou équivalent »"]}},{"id":"livrables","titre":"4. Livrables et calendrier","obligatoire":true,"consigne":"Lister chaque livrable, son format, son échéance et son critère d'acceptation.","contenu":"L1 — Plan de travail et plan de passation : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL2 — Rapports trimestriels d'avancement : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL3 — Tableaux de bord de suivi : échéance [●] ; validé par [●] sous [●] jours ouvrés.\nL4 — Rapport de fin de mission et plan de pérennisation : échéance [●] ; validé par [●] sous [●] jours ouvrés.","guide":{"objectif":"Rendre le paiement vérifiable : un livrable ou un jalon = une preuve datée, validée par une personne désignée.","points":["Plan de travail et plan de passation","Rapports trimestriels d'avancement","Tableaux de bord de suivi","Rapport de fin de mission et plan de pérennisation","Lien entre livrable et paiement"],"exemple":"Plan de travail et plan de passation : au plus tard à T0 + 30 jours calendaires, validé par le comité de suivi sous 10 jours ouvrés.","erreurs":["Livrables sans échéance","Aucun critère d'acceptation","Délai de validation non fixé"]}},{"id":"profil","titre":"5. Qualifications et moyens requis","obligatoire":true,"consigne":"Exigences proportionnées à l'objet : trop faibles, risque de mauvaise exécution ; trop fortes, exclusion des PME.","contenu":"- Chef de projet / coordonnateur confirmé : [●]\n- Spécialiste en passation de marchés : [●]\n- Spécialiste en gestion financière : [●]\n- Références d'AMO sur des programmes comparables : [●]\n- Connaissance des règles des bailleurs : [●]\n\nGroupement et sous-traitance : [●]","guide":{"objectif":"Fixer des exigences proportionnées et vérifiables, ouvertes aux PME locales.","points":["Chef de projet / coordonnateur confirmé","Spécialiste en passation de marchés","Spécialiste en gestion financière","Références d'AMO sur des programmes comparables","Connaissance des règles des bailleurs","Possibilité de groupement et de sous-traitance (plafond de 40 %)"],"exemple":"Chef de projet / coordonnateur confirmé : au moins [●] ans d'expérience et [●] références similaires sur les 5 dernières années.","erreurs":["Exiger un chiffre d'affaires supérieur au double du marché","Imposer une marque d'équipement","Exclure implicitement les PME"]}},{"id":"duree","titre":"6. Durée et lieu d'exécution","obligatoire":true,"consigne":"Délai réaliste, point de départ précis, lieux.","contenu":"Le délai d'exécution est de [●] jours calendaires à compter de l'ordre de service de démarrage. Lieu(x) d'exécution : [●].","guide":{"objectif":"Donner un délai réaliste et un point de départ précis.","points":["Délai en jours calendaires et point de départ (ordre de service)","Lieux d'exécution (régions, communes, sites)","Jalons intermédiaires","Durée de la mission","Calendrier du programme"],"exemple":"Le délai d'exécution est de 120 jours calendaires à compter de l'ordre de service de démarrage. Lieu d'exécution : [commune, région].","erreurs":["Délai en « mois » sans date de départ","Délai incompatible avec les procédures de recours","Plusieurs lieux non listés"]}},{"id":"specifiques","titre":"7. Exigences propres au secteur (normes, sécurité, environnement)","obligatoire":true,"consigne":"Normes, réglementation sectorielle, sécurité, environnement : Code des marchés publics et règles du bailleur (à confirmer) ; Procédures fiduciaires du programme.","contenu":"Normes et réglementation applicables : [●]\n\nExigences de sécurité, d'hygiène et d'environnement : [●]","guide":{"objectif":"Citer les règles propres au métier, sans en inventer : en cas de doute, renvoyer à l'autorité sectorielle compétente.","points":["Références usuelles (à confirmer auprès de l'autorité compétente) : Code des marchés publics et règles du bailleur (à confirmer)","Références usuelles (à confirmer auprès de l'autorité compétente) : Procédures fiduciaires du programme","Références usuelles (à confirmer auprès de l'autorité compétente) : Règles de déontologie et conflits d'intérêts","L'assistant conseille, l'autorité décide","Éviter la substitution durable à l'équipe de l'autorité","Définir le nombre de jours-experts et leur répartition","Conflit d'intérêts avec les entreprises du programme"],"exemple":"Le titulaire respecte les normes sénégalaises (ASN) ou internationales équivalentes applicables à [●], ainsi que la réglementation sectorielle en vigueur.","erreurs":["Citer un texte sans en vérifier la version en vigueur","Norme étrangère sans équivalent admis","Oublier les exigences de sécurité et d'environnement"]}},{"id":"suivi","titre":"8. Suivi, contrôle et réception","obligatoire":true,"consigne":"Qui contrôle, à quel rythme, selon quels critères de réception.","contenu":"Un comité de suivi se réunit tous les [●] jours.\n\nCritères de réception :\n- Rapports périodiques conformes\n- Plan de passation respecté\n- Capacités de l'équipe renforcées\n- Rapport de fin de mission remis\n\nPénalités applicables : voir la clause type « Pénalités de retard ».","guide":{"objectif":"Dire comment l'autorité contrôle et réceptionne, pour éviter les litiges de fin de marché.","points":["Rapports périodiques conformes","Plan de passation respecté","Capacités de l'équipe renforcées","Rapport de fin de mission remis","Responsable du suivi et fréquence des rapports","Réception provisoire puis définitive, garantie"],"exemple":"La réception provisoire est prononcée après contrôle des livrables par la commission de réception ; la réception définitive intervient à l'expiration de la garantie.","erreurs":["Aucun responsable désigné","Réception sans critères","Oublier la garantie après réception"]}},{"id":"obligations","titre":"9. Obligations des parties, confidentialité et propriété intellectuelle","obligatoire":false,"consigne":"Obligations de chaque partie ; renvoi aux clauses types (garanties, propriété intellectuelle, avenants).","contenu":"","guide":{"objectif":"Répartir clairement les obligations et renvoyer aux clauses types plutôt que les recopier.","points":["Obligations de l'autorité (accès, données, validation dans les délais)","Obligations du titulaire (moyens, confidentialité, rapports)","Garanties et assurances requises","Propriété et restitution des livrables, données et équipements"],"exemple":"L'autorité contractante met à disposition [●] dans un délai de [●] jours après l'ordre de service. Le titulaire garde confidentielles les informations reçues.","erreurs":["Obligations unilatérales","Confidentialité sans durée","Propriété des livrables non précisée"]}},{"id":"budget","titre":"10. Estimation budgétaire","obligatoire":false,"consigne":"Ligne budgétaire et estimation prévisionnelle (hors taxes), méthode d'estimation.","contenu":"Estimation prévisionnelle : {{montant_estime}} FCFA, imputée sur la ligne budgétaire {{ligne_budgetaire}} (exercice {{annee}}).","guide":{"objectif":"Rendre le prix estimé traçable (il détermine la procédure et les seuils).","points":["Ligne budgétaire et exercice","Méthode d'estimation (références, prix antérieurs, catalogue d'accords-cadres)","Montant estimé hors taxes"],"exemple":"Estimation : {{montant_estime}} FCFA sur la ligne {{ligne_budgetaire}}, établie à partir des marchés similaires de [années].","erreurs":["Estimation sans méthode","Fractionner pour passer sous un seuil","Confondre HT et TTC"]}}]$j$::jsonb, $j${"famille":"SERVICES","version":2,"questions":["Quel programme et quelle durée de mission ?","Quelles fonctions l'assistant doit-il couvrir ?","Quel financeur et quelles règles ?","Quelle équipe sera accompagnée ?","Comment assurer le transfert de compétences ?"],"references":["Code des marchés publics et règles du bailleur (à confirmer)","Procédures fiduciaires du programme","Règles de déontologie et conflits d'intérêts"],"vigilance":["L'assistant conseille, l'autorité décide","Éviter la substitution durable à l'équipe de l'autorité","Définir le nombre de jours-experts et leur répartition","Conflit d'intérêts avec les entreprises du programme"]}$j$::jsonb FROM corps_metiers cm WHERE cm.code = 'AMO_GESTION_PROJET'
